  openDashboardStream: {
    parameters: {
      query?: never;
      header?: {
        'Last-Event-ID'?: string;
      };
      path?: never;
      cookie?: never;
    };
    requestBody?: never;
    responses: {
      /** @description Fluxo de eventos do painel. Cada evento tem id (b<marca>.l<marca>.s<marca>, só para Last-Event-ID), event (o nome) e data: o JSON de um destes envelopes, conforme o nome: bot.state DashboardBotStateEvent, trade.recorded DashboardTradeRecordedEvent, pnl.updated DashboardPnlUpdatedEvent, data.status DashboardDataStatusEvent, heartbeat DashboardHeartbeatEvent, auth.expired DashboardAuthExpiredEvent (U9) */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'text/event-stream':
            | components['schemas']['DashboardBotStateEvent']
            | components['schemas']['DashboardTradeRecordedEvent']
            | components['schemas']['DashboardPnlUpdatedEvent']
            | components['schemas']['DashboardDataStatusEvent']
            | components['schemas']['DashboardHeartbeatEvent']
            | components['schemas']['DashboardAuthExpiredEvent']
            | components['schemas']['RealOrderStateChanged']
            | components['schemas']['RealSigningSessionOpened']
            | components['schemas']['RealConditionalStateChanged'];
        };
      };
      /** @description UNAUTHENTICATED */
      401: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'text/event-stream': string;
        };
      };
      /** @description RATE_LIMITED: a pessoa já tem 5 canais abertos; Retry-After diz quando tentar de novo (U9, NFR2.1) */
      429: {
        headers: {
          'Retry-After'?: number;
          [name: string]: unknown;
        };
        content: {
          'application/problem+json': components['schemas']['Problem'];
        };
      };
    };
  };
  acceptTerms: {
    parameters: {
      query?: never;
      header: {
        'Idempotency-Key': string;
      };
      path?: never;
      cookie?: never;
    };
    requestBody: {
      content: {
        'application/json': components['schemas']['AcceptTermsRequest'];
      };
    };
    responses: {
      /** @description Aceite registrado, ou já existente para a versão (sem nova gravação); a mesma chave devolve a mesma resposta */
      200: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/json': components['schemas']['TermsStatus'];
        };
      };
      /** @description VALIDATION_FAILED: versão ausente, vazia ou com mais de 32 caracteres, campo desconhecido ou Idempotency-Key ausente */
      400: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/problem+json': components['schemas']['Problem'];
        };
      };
      /** @description UNAUTHENTICATED */
      401: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/problem+json': components['schemas']['Problem'];
        };
      };
      /** @description FORBIDDEN_ROLE para token de administrador */
      403: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/problem+json': components['schemas']['Problem'];
        };
      };
      /** @description TERMS_VERSION_OUTDATED (o corpo traz a versão vigente em currentVersion) ou IDEMPOTENCY_CONFLICT (mesma chave com outra versão) */
      409: {
        headers: {
          [name: string]: unknown;
        };
        content: {
          'application/problem+json': components['schemas']['Problem'];
        };
      };
    };
  };
